import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int budget = fs.nextInt();
        int n = fs.nextInt();

        int[] minPrice = new int[101];
        Arrays.fill(minPrice, Integer.MAX_VALUE);

        for (int i = 0; i < n; i++) {
            int type = fs.nextInt();
            int price = fs.nextInt();
            minPrice[type] = Math.min(minPrice[type], price);
        }

        int[] prices = new int[101];
        int count = 0;
        for (int price : minPrice) {
            if (price != Integer.MAX_VALUE) {
                prices[count++] = price;
            }
        }

        Arrays.sort(prices, 0, count);
        int answer = 0;
        for (int i = 0; i < count && budget >= prices[i]; i++) {
            budget -= prices[i];
            answer++;
        }

        System.out.println(answer);
    }

    private static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }
    }
}
